<?php
use App\Models\User;use App\Services\LedgerService;use Illuminate\Support\Facades\DB;
test('paper wallet credits create balanced ledger entries',function(){$u=User::factory()->create();app(LedgerService::class)->creditPaperWallet($u,'100.00000000');$w=app(LedgerService::class)->wallet($u);expect(app(LedgerService::class)->balanceUnits($w))->toBe(10000000000);$tx=DB::table('ledger_transactions')->first();$entries=DB::table('ledger_entries')->where('ledger_transaction_id',$tx->id)->get();expect($entries)->toHaveCount(2);});
test('market and trading screens require authentication',function(){$this->get('/markets')->assertRedirect('/login');$this->get('/trading')->assertRedirect('/login');$this->get('/portfolio')->assertRedirect('/login');});
test('client portfolio displays zero until simulation credits are issued',function(){$u=User::factory()->create();$this->actingAs($u)->get('/portfolio')->assertOk()->assertSee('0.00000000')->assertSee('Paper wallet only');});
test('paper trade opening is blocked when quote is missing',function(){$u=User::factory()->create();app(LedgerService::class)->creditPaperWallet($u,'100.00000000');$this->actingAs($u)->postJson('/trading/paper',['symbol'=>'BTCUSDT','direction'=>'UP','stake'=>'10','duration'=>60])->assertStatus(422)->assertJsonFragment(['message'=>'No fresh market quote is available for this pair. Trading is blocked.']);});
